def recopier_infos_fichier(apps, schema_editor):
    """Recopie le nom et la taille des fichiers encore présents dans les anciennes lignes du journal."""
    LogAcces = apps.get_model('partage', 'LogAcces')
    for log in LogAcces.objects.filter(fichier__isnull=False).select_related('fichier').iterator():
        log.nom_fichier = log.fichier.nom_original[:255]
        log.taille_fichier = log.fichier.taille
        log.save(update_fields=['nom_fichier', 'taille_fichier'])


